#!/usr/bin/env python3
"""Validate deterministic custom honey sprites generated by Gradle."""
import hashlib
import struct
import sys
from pathlib import Path
NAMES = ["clover_honey_bottle","lavender_honey_bottle","buckwheat_honey_bottle","sunflower_honey_bottle","dandelion_honey_bottle","poppy_honey_bottle","allium_honey_bottle","cornflower_honey_bottle","azure_bluet_honey_bottle","blue_orchid_honey_bottle","lily_of_the_valley_honey_bottle","oxeye_daisy_honey_bottle","torchflower_honey_bottle","red_tulip_honey_bottle","orange_tulip_honey_bottle","white_tulip_honey_bottle","pink_tulip_honey_bottle","wither_rose_honey_bottle","blackberry_honey_bottle","blackcurrant_honey_bottle","chive_honey_bottle","pumpkin_blossom_honey_bottle","wildflower_honey_bottle"]
root = Path(sys.argv[1]) if len(sys.argv)>1 else Path("build/generated/resources/cropAssets")
hashes=set()
for name in NAMES:
    data=(root/"assets/gugugaga/textures/item/honey"/f"{name}.png").read_bytes()
    assert data[:8] == b"\x89PNG\r\n\x1a\n", f"{name}: invalid PNG signature"
    assert struct.unpack(">II",data[16:24]) == (16,16), f"{name}: expected a 16x16 sprite"
    hashes.add(hashlib.sha256(data).hexdigest())
assert len(hashes)==len(NAMES), "Honey bottle textures must be pixel-distinct"
print(f"HONEY_ART_OK: {len(NAMES)} distinct 16x16 generated bottle textures")
